sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float strength;
uniform float wavelength;
uniform float speed;
uniform float phase;
uniform float direction;
uniform float bias;
uniform float damping;
uniform float reach;
uniform float shading;
uniform float inward;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 ctr = center * size;
    float2 d = coord - ctr;
    float dist = length(d);
    float2 dir = d / max(dist, 0.001);
    float sgn = inward > 0.5 ? 1.0 : -1.0;
    float ph = dist * 6.2831853 / max(wavelength, 1.0) + sgn * time * speed * 6.2831853 + radians(phase);
    float env = mix(1.0, exp(-dist / (max(reach, 0.01) * length(size))), damping);
    float w = sin(ph) * strength * env;
    float2 axis = float2(cos(radians(direction)), sin(radians(direction)));
    float2 disp = mix(dir, axis, bias) * w;
    float4 r = tex(coord + disp);
    r = float4(r.rgb * (1.0 + cos(ph) * env * shading), r.a);
    return fin(c, r, opacity);
}
